import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·23","description":"易小帖 - 卷三·23","frontmatter":{"title":"卷三·23","description":"易小帖 - 卷三·23"},"headers":[],"relativePath":"zh/classics/yixiaotie/091.md","filePath":"zh/classics/yixiaotie/091.md"}'),o={name:"zh/classics/yixiaotie/091.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·23",tabindex:"-1"},[r("卷三·23 "),e("a",{class:"header-anchor",href:"#卷三·23","aria-label":"Permalink to “卷三·23”"},"​")],-1),e("p",null,"鼎之九二曰「我仇有疾」，王弼以六五為九二仇，則以二五本相應。且鼎以大壯之五剛為二所易*，則二為我匹，其說是也。若虞氏以九四為二仇，而《程傳》以初六為二仇，則雜亂矣。無論五為二應，且為二易，二必匹五，而即以有疾推之，惟六五居離中而離伏坎位，坎為心疾，故有疾。若初四則何疾之有？朱漢上引偽《子夏傳》以為二與四為仇。四以近權惡我專任怨耦敵我，則既襲仲翔舊說，而又以仇為怨恨，倍失之矣。隋時偽《子夏傳》以五為仇，且註曰：君子好仇。見陸氏《釋文》。而宋時偽《子夏傳》則偽之又偽，反以四為仇，且以怨耦曰仇為解，則正相矛盾。緣後之作偽者，不深考舊文，凡唐儒所引者，皆不之顧，故並無一合，而漢上引以解經，豈不舛乎。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
